mapper.select:
SELECT id, user_id, status, total_amount, pay_amount,
       receiver_name, receiver_phone, receiver_address
FROM `order_info`

    id <= #{cursor}
    AND user_id = #{userId}
    AND status = #{status}
    AND total_amount >= #{minAmount}
    AND total_amount <= #{maxAmount}
    AND created_at >= #{createdFrom}
    AND created_at <= #{createdTo}

ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE `order_info`
SET status = 1, pay_amount = #{payAmount}
WHERE id = #{id} AND status = 0

choose.when:
SELECT DATE(o.created_at) AS stat_key, COUNT(*) AS order_count, SUM(o.total_amount) AS total_amount FROM `order_info` o WHERE o.created_at >= #{beginDate}
AND o.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = #{status}
GROUP BY DATE(o.created_at) ORDER BY stat_key ASC

choose.otherwise:
SELECT o.status AS stat_key, COUNT(*) AS order_count, SUM(o.total_amount) AS total_amount FROM `order_info` o WHERE o.created_at >= #{beginDate} AND o.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = #{status}
GROUP BY o.status ORDER BY stat_key ASC
